SELECT generation_job_id, compute_task_id, compute_attempt_id, operation_plan_id, input_snapshot_json::text AS input_snapshot_json, input_fingerprint, id, row_version, created_at, updated_at, shot_id, attempt_number, provider, model, generation_mode, output_asset_id, source_duration_ms, metrics_json::text AS metrics_json, validation_status, validation_failure_category, validation_failure_reason, validation_retry_recommendation, status FROM takes WHERE shot_id IN
#{id}
ORDER BY shot_id ASC, attempt_number ASC, id ASC
